const wa='https://wa.me/9647722282272?text=';
const models=[
{id:'iphone15',name:'iPhone 15 Pro',brand:'Apple',type:'phone',image:'iphone15.png',variant:'256 GB',description:'خيار لمحبي التصوير والأداء القوي، بتصميم تيتانيوم ومنفذ USB-C. مناسب للتطبيقات الثقيلة والتصوير اليومي وتحرير المحتوى.',specs:[['الشاشة','6.1 بوصة · OLED · حتى 120Hz'],['المعالج','Apple A17 Pro'],['التخزين المعروض','256 GB'],['الكاميرا الرئيسية','48 MP'],['الاتصال والشحن','5G · USB-C']],prices:{new:[1000000,1300000],used:[750000,950000]},source:'https://support.apple.com/en-us/111829',market:'https://iq.opensooq.com/en/mobile-phones-tablets/mobile-phones/mobiles-apple/iphone-15-pro'},
{id:'iphone13',name:'iPhone 13',brand:'Apple',type:'phone',image:'iphone13.png',variant:'128 GB',description:'موبايل عملي للاستخدام اليومي والتواصل والتصوير، بشاشة OLED ومعالج A15 Bionic. خيار لمن يريد تجربة آيفون بميزانية أقل.',specs:[['الشاشة','6.1 بوصة · Super Retina XDR'],['المعالج','Apple A15 Bionic'],['التخزين المعروض','128 GB'],['الكاميرات الخلفية','مزدوجة · 12 MP'],['الاتصال والشحن','5G · Lightning']],prices:{new:[550000,750000],used:[350000,500000]},source:'https://support.apple.com/en-us/111872',market:'https://iq.opensooq.com/en/mobile-phones-tablets/mobile-phones/mobiles-apple/iphone-13/128-gb'},
{id:'canon',name:'Canon EOS R50',brand:'Canon',type:'camera',image:'canon.jpg',variant:'Twin Kit · 18–45 + 55–210 mm',description:'كاميرا ميرورلس خفيفة للصور والفيديو، مناسبة للتعلم وصناعة المحتوى. النطاق المعروض لطقم عدستين، ويختلف عن سعر الهيكل وحده.',specs:[['المستشعر','APS-C · 24.2 MP'],['الفيديو','4K حتى 30 إطار/ثانية'],['الشاشة','متحركة قابلة للمس'],['نوع العدسة','Canon RF / RF-S'],['الطقم المسعّر','RF-S 18–45 + RF-S 55–210 mm']],prices:{new:[1250000,1450000],used:[850000,1150000]},source:'https://www.canon.com.au/cameras/eos-r50',market:'https://store.alafrah.iq/product/canon-r50-18-45-rf55-210s-twin-kit/'},
{id:'sony',name:'Sony ZV-E10',brand:'Sony',type:'camera',image:'sony.jpg',variant:'Kit · 16–50 mm',description:'كاميرا موجهة للفلوغ وصناعة المحتوى، بمستشعر APS-C وعدسات قابلة للتبديل. الشاشة المتحركة تسهّل تصوير نفسك والمنتجات.',specs:[['المستشعر','APS-C · 24.2 MP'],['الفيديو','4K حتى 30 إطار/ثانية'],['الشاشة','جانبية متحركة'],['نوع العدسة','Sony E-mount'],['الطقم المسعّر','عدسة 16–50 mm']],prices:{new:[900000,1100000],used:[600000,800000]},source:'https://www.sony.ca/en/electronics/support/e-mount-body-zv-e-series/zv-e10/specifications',market:'https://store.alafrah.iq/product/sony-zv-e10-mirrorless-camera-with-16-50mm-lens/'}
];
const departments=[{id:'phones',type:'phone',title:'قسم الموبايلات',intro:'آيفون · موديلات وسعات مختلفة'},{id:'cameras',type:'camera',title:'قسم الكاميرات',intro:'Canon وSony · كاميرات ميرورلس لصناعة المحتوى'}];
const state={phone:{condition:'all',brand:'all'},camera:{condition:'all',brand:'all'}};const labels={new:'جديد',used:'مستعمل'};const money=n=>n.toLocaleString('en-US');const range=(m,c)=>`من ${money(m.prices[c][0])} إلى ${money(m.prices[c][1])} د.ع`;
const inquiry=(m,c)=>wa+encodeURIComponent(`مرحبا معرض دبي، أستفسر عن ${m.name} — ${m.variant} (${labels[c]}). هل متوفر؟ أحتاج السعر النهائي وصور القطعة وتفاصيل حالتها وملحقاتها.`);
document.querySelector('#departments').innerHTML=departments.map(d=>`<section id="${d.id}" class="department" data-type="${d.type}"><div class="department-heading"><div><span class="kicker">${d.intro}</span><h2>${d.title}</h2></div><span class="result-count" aria-live="polite"></span></div><div class="department-toolbar"><div class="tabs" role="group" aria-label="حالة الأجهزة في ${d.title}">${[['all','الكل'],['new','الجديد'],['used','المستعمل']].map(([v,l])=>`<button data-condition="${v}" class="${v==='all'?'selected':''}" aria-pressed="${v==='all'}">${l}</button>`).join('')}</div><label class="brand-filter">الماركة <select aria-label="ماركة ${d.title}"><option value="all">كل الماركات</option>${[...new Set(models.filter(m=>m.type===d.type).map(m=>m.brand))].map(b=>`<option>${b}</option>`).join('')}</select></label></div><div class="products"></div><p class="empty" hidden>ماكو أجهزة مطابقة لبحثك بهذا القسم. جرّب موديل ثاني أو غيّر الفلاتر.</p></section>`).join('');
function render(){const query=document.querySelector('#search').value.trim().toLowerCase();for(const d of departments){const root=document.querySelector('#'+d.id);const s=state[d.type];const entries=models.filter(m=>m.type===d.type&&(s.brand==='all'||m.brand===s.brand)&&(m.name+' '+m.brand+' '+m.variant+' '+m.description+' '+m.specs.flat().join(' ')).toLowerCase().includes(query)).flatMap(m=>(s.condition==='all'?['new','used']:[s.condition]).map(c=>({m,c})));root.querySelector('.products').innerHTML=entries.map(({m,c})=>`<article class="product"><button class="product-art photo-art" data-detail="${m.id}" data-state="${c}" aria-label="عرض تفاصيل ${m.name} ${labels[c]}"><span class="condition-tag ${c}">${labels[c]}</span><img loading="lazy" src="assets/${m.image}" alt="صورة موديل ${m.name} وليست القطعة المعروضة للبيع"><span class="photo-caption">صورة الموديل</span></button><div class="product-info"><span class="category">${m.brand} · ${m.variant}</span><h3>${m.name}</h3><p class="short-description">${m.description}</p><div class="price-label">سعر تقريبي · ${labels[c]}</div><div class="price-range">${range(m,c)}</div><small class="availability">التوفر يُؤكّد من المعرض</small><button class="details-btn" data-detail="${m.id}" data-state="${c}">المواصفات والتفاصيل <span>←</span></button><a href="${inquiry(m,c)}" target="_blank" rel="noopener">اسأل عن الجهاز على واتساب ↗</a></div></article>`).join('');root.querySelector('.empty').hidden=entries.length>0;root.querySelector('.result-count').textContent=entries.length+' خيارات للعرض'}}
const dialog=document.querySelector('#device-dialog');let opener;
function openDetails(id,c){const m=models.find(x=>x.id===id);if(!m||!labels[c])return;document.querySelector('#detail-content').innerHTML=`<div class="detail-photo"><img src="assets/${m.image}" alt="${m.name}"><small>صورة مرجعية للموديل؛ اطلب صور القطعة الفعلية عبر واتساب.</small></div><div class="detail-info"><span class="condition-tag ${c}">${labels[c]}</span><h2 id="detail-title" dir="ltr">${m.name}</h2><p>${m.description}</p><div class="price-label">النطاق التقريبي — ${m.variant}</div><div class="price-range">${range(m,c)}</div><p class="detail-note">تقدير استرشادي، وليس عرض بيع مؤكداً. السعر النهائي بعد التأكد من النسخة والحالة والملحقات.</p><dl>${m.specs.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl><h3>${c==='used'?'تفاصيل القطعة المستعملة':'قبل شراء الجهاز الجديد'}</h3><p>${c==='used'?(m.type==='phone'?'نسبة البطارية، حالة الشاشة والهيكل، سجل الصيانة والقطع المستبدلة، والملحقات: تُحدّد لكل قطعة عند الاستفسار.':'عدد لقطات الشتر إن توفر، حالة المستشعر والعدسات، البطارية والملحقات: تُحدّد لكل قطعة عند الاستفسار.'):'تأكد من ختم العلبة، النسخة، الضمان والملحقات المتضمنة مع المعرض. عرض هذا الخيار لا يعني توفر مخزون حالياً.'}</p><a class="btn" href="${inquiry(m,c)}" target="_blank" rel="noopener">اطلب السعر وصور القطعة ↗</a><details class="sources"><summary>مصادر الموديل والسعر</summary><a href="${m.source}" target="_blank" rel="noopener">المواصفات الرسمية ↗</a><a href="${m.market}" target="_blank" rel="noopener">مرجع سوقي للأسعار والصور ↗</a><p>المدى المعروض تقدير تحريري، وقد يختلف عن السعر المنشور بالمصدر. صور الهواتف من Apple، وصور الكاميرات من صفحة المنتج لدى الأفراح.</p></details></div>`;dialog.showModal()}
document.querySelector('#departments').addEventListener('click',e=>{const filter=e.target.closest('[data-condition]');if(filter){const root=filter.closest('.department');state[root.dataset.type].condition=filter.dataset.condition;root.querySelectorAll('[data-condition]').forEach(b=>{b.classList.toggle('selected',b===filter);b.setAttribute('aria-pressed',b===filter)});render();return}const button=e.target.closest('[data-detail]');if(button){opener=button;openDetails(button.dataset.detail,button.dataset.state)}});
document.querySelectorAll('.brand-filter select').forEach(select=>select.addEventListener('change',()=>{state[select.closest('.department').dataset.type].brand=select.value;render()}));document.querySelector('#search').addEventListener('input',render);document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>opener?.focus());
document.querySelector('#sell-form').addEventListener('submit',e=>{e.preventDefault();const message=`مرحبا معرض دبي، عندي جهاز للبيع.\nالنوع: ${document.querySelector('#kind').value}\nالموديل: ${document.querySelector('#model').value.trim()}\nالحالة والملاحظات: ${document.querySelector('#condition').value.trim()}`;window.open(wa+encodeURIComponent(message),'_blank','noopener,noreferrer')});render();

// Direct views: navigation selects content instead of scrolling past other sections.
const navMenus=[...document.querySelectorAll('.nav-dropdown')];
navMenus.forEach(menu=>menu.addEventListener('toggle',()=>{if(menu.open)navMenus.forEach(other=>{if(other!==menu)other.open=false})}));
document.addEventListener('click',event=>{if(!event.target.closest('.nav-dropdown'))navMenus.forEach(menu=>menu.open=false)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const menu=navMenus.find(m=>m.open);if(menu){menu.open=false;menu.querySelector('summary').focus()}}});
function selectView(){const [raw,condition='all',brand='all']=decodeURIComponent(location.hash.slice(1)||'home').split('/');const view=['home','phones','cameras','sell','branches'].includes(raw)?raw:'home';const catalog=view==='phones'||view==='cameras';document.querySelector('#home-view').hidden=view!=='home';document.querySelector('#collection').hidden=!catalog;document.querySelector('#sell').hidden=view!=='sell';document.querySelector('#branches').hidden=view!=='branches';
if(catalog){const type=view==='phones'?'phone':'camera';state[type].condition=['all','new','used'].includes(condition)?condition:'all';state[type].brand=models.some(m=>m.type===type&&m.brand===brand)?brand:'all';document.querySelector('#search').value='';departments.forEach(d=>{const root=document.querySelector('#'+d.id);root.hidden=d.id!==view;if(d.id===view){root.querySelectorAll('[data-condition]').forEach(b=>{const selected=b.dataset.condition===state[type].condition;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected)});root.querySelector('.brand-filter select').value=state[type].brand}});render();document.querySelectorAll('.department-links a').forEach(a=>{a.classList.toggle('selected',a.hash==='#'+view);a.setAttribute('aria-current',a.hash==='#'+view?'page':'false')})}
navMenus.forEach(menu=>{menu.open=false;menu.classList.toggle('current',!!menu.querySelector(`a[href="#${view}"]`))});document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===view);a.setAttribute('aria-current',a.dataset.nav===view?'page':'false')});document.title=(view==='phones'?'الموبايلات':view==='cameras'?'الكاميرات':view==='sell'?'بيع جهازك':view==='branches'?'فروعنا':'الرئيسية')+' | معرض دبي';document.body.dataset.view=view;window.scrollTo({top:0,behavior:'instant'});const heading=document.querySelector(catalog?'#'+view+' h2':view==='home'?'.hero h1':'#'+view+' h2');if(heading){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true})}}
window.addEventListener('hashchange',selectView);document.addEventListener('click',event=>{const a=event.target.closest('a[href^="#"]');if(a&&a.hash===location.hash){event.preventDefault();selectView()}});
const motionButton=document.querySelector('#motion-toggle');let motionOff=window.matchMedia('(prefers-reduced-motion: reduce)').matches;try{motionOff=motionOff||localStorage.getItem('dubai-motion')==='off'}catch{}
function updateMotion(){document.body.classList.toggle('motion-paused',motionOff);motionButton.textContent=motionOff?'▷':'Ⅱ';motionButton.setAttribute('aria-pressed',String(motionOff));motionButton.setAttribute('aria-label',motionOff?'تشغيل حركة الخلفية':'إيقاف حركة الخلفية');motionButton.title=motionOff?'تشغيل حركة الخلفية':'إيقاف حركة الخلفية'}motionButton.addEventListener('click',()=>{motionOff=!motionOff;try{localStorage.setItem('dubai-motion',motionOff?'off':'on')}catch{}updateMotion()});updateMotion();selectView();
